echo '<li><a href="https://github.com/Vlad-BloodMoon/BloodMoon-Voice/blob/main/docs/TROUBLESHOOTING.md" target="_blank" rel="noopener">Guide de dépannage détaillé</a></li>';
echo '<li><a href="https://github.com/Vlad-BloodMoon/BloodMoon-Voice/blob/main/docs/SECURITY.md" target="_blank" rel="noopener">Guide sécurité</a></li>';
echo '</ul>';end_page();